<script setup lang="ts">
import {computed,ref,watch} from 'vue';
import PlanningMap from './PlanningMap.vue';
import {date,money} from '../fulfillment';
const props=defineProps<{plan:any}>();const activeId=ref('');watch(()=>props.plan,p=>{activeId.value=p.candidates[0]?.id||'';},{immediate:true});
const active=computed(()=>props.plan.candidates.find((v:any)=>v.id===activeId.value));
const hours=(n:number)=>{const total=Math.round(n/3600),days=Math.floor(total/24),h=total%24;return (days?days+'天':'')+(h?h+'小时':'')||'不足1小时';};
const modes:Record<string,string>={ROAD:'公路',RAIL:'铁路',WATER:'水运'};
const mapSegments=computed(()=>active.value?.segments.map((s:any)=>({...s,displayPath:s.displayPath||s.priceSnapshot?.displayPath}))||[]);
const maxCost=computed(()=>Math.max(1,...props.plan.candidates.filter((c:any)=>c.costCents!=null).map((c:any)=>c.costCents)));
</script>
<template><section class="agent-plan-results"><div v-if="plan.candidates.length" class="recommend-grid"><button v-for="c in plan.candidates" :key="c.id" :class="{selected:activeId===c.id}" :aria-pressed="activeId===c.id" @click="activeId=c.id"><span class="recommend-label">{{c.recommendationLabel}}</span><strong>{{c.familyLabel||c.modes.map((m:string)=>modes[m]).join(' + ')}}</strong><div class="route-value"><b>{{c.costCents==null?'报价待补充':money(c.costCents/(plan.input.quantity||1))+'/吨'}}</b><span>{{hours(c.durationSeconds)}}</span></div><div class="route-score"><span>可靠性 {{c.reliability}} 分</span><span>{{c.segments.length}} 个区段</span></div></button></div><template v-if="active"><div class="plan-comparison"><h4>推荐路线比较</h4><div v-for="c in plan.candidates" :key="c.id" class="comparison-row"><span>{{c.familyLabel}}</span><div><i :style="{width:c.costCents!=null?Math.max(6,c.costCents/maxCost*100)+'%':'0%'}"/></div><b>{{c.costCents==null?'待报价':money(c.costCents)}}</b></div><small>全程参考费用 · {{plan.input.quantity}} 吨；可靠性为测算评分。</small></div><div class="agent-route-map"><PlanningMap :segments="mapSegments"/></div><el-table :data="active.segments" size="small"><el-table-column type="expand"><template #default="{row}"><div class="segment-fees"><strong>区段费用明细</strong><el-table :data="row.fees||[]" size="small"><el-table-column prop="name" label="费用项目"/><el-table-column label="单价"><template #default="{row:fee}">{{fee.rate==null?'待报价':Number(fee.rate).toLocaleString('zh-CN',{maximumFractionDigits:3})}} {{fee.unit}}</template></el-table-column><el-table-column prop="quantity" label="数量" width="100"/><el-table-column label="金额" width="130"><template #default="{row:fee}">{{fee.costCents==null?'待报价':money(fee.costCents)}}</template></el-table-column></el-table><p>{{row.priceSnapshot.assumptions||'费用为参考测算，实际成交费用由业务双方确认。'}}</p></div></template></el-table-column><el-table-column label="区段" width="75"><template #default="{row}">{{modes[row.mode]}}</template></el-table-column><el-table-column label="运输路线" min-width="200"><template #default="{row}">{{row.origin.name}} → {{row.destination.name}}</template></el-table-column><el-table-column label="时效" width="110"><template #default="{row}">{{hours(row.durationSeconds+row.waitSeconds)}}</template></el-table-column><el-table-column label="参考费用" width="120"><template #default="{row}">{{row.costCents==null?'待报价':money(row.costCents)}}</template></el-table-column></el-table><p class="recommend-reason">{{active.recommendationReasons?.join(' ')}}</p><p class="arrival-note">{{active.arrivalAt?'预计到达 '+date(active.arrivalAt):'班期和实际到达时间需与承运方确认'}}。</p><details><summary>费用、班期及路线依据</summary><p v-for="w in active.warnings" :key="w">{{w}}</p><p v-for="u in plan.unavailable||[]" :key="u.objective">{{u.message}}</p></details></template><el-empty v-else description="当前条件下没有可推荐的路线，可进入方案求解调整条件" :image-size="65"/><div class="more-plan"><span>本次共 {{plan.total}} 条可行方案</span><router-link :to="'/plans/solve?runId='+plan.id">查看更多路径推荐 →</router-link></div></section></template>
<style scoped>.segment-fees{padding:16px 20px;background:#f8fbff}.segment-fees>strong{font-size:12px;display:block;margin-bottom:12px}.segment-fees>p{font-size:11px;color:#687b93;line-height:1.8}.agent-plan-results{margin-top:20px}.recommend-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:12px}.recommend-grid>button{border:1px solid #e3eaf5;border-radius:10px;background:#fbfcff;text-align:left;padding:16px;cursor:pointer;color:#405069}.recommend-grid>button.selected{border-color:#5c94fa;background:#f0f6ff;box-shadow:0 0 0 1px #5c94fa}.recommend-label{font-size:11px;color:#3275d6;display:block;min-height:32px;line-height:1.5}.recommend-grid strong{font-size:14px;display:block;margin:5px 0 15px}.route-value{display:flex;gap:12px;align-items:center;justify-content:space-between}.route-value b{font-size:17px;color:#246bd1}.route-value>span{font-size:12px;color:#6e7e93}.route-score{display:flex;justify-content:space-between;font-size:11px;color:#8190a5;margin-top:15px}.plan-comparison{padding:18px 0}.plan-comparison h4{font-size:13px;margin:0 0 12px}.comparison-row{display:flex;gap:12px;align-items:center;margin:9px 0;font-size:12px}.comparison-row>span{width:130px}.comparison-row>div{flex:1;background:#f2f5fa;height:9px;border-radius:5px;overflow:hidden}.comparison-row i{display:block;height:100%;background:#78a8f1;border-radius:5px}.comparison-row b{width:110px;text-align:right;font-weight:500}.plan-comparison small{font-size:11px;color:#929eb0}.agent-route-map{height:380px;margin:0 0 18px}.agent-route-map :deep(.planning-map){min-height:380px}.recommend-reason,.arrival-note{font-size:12px;line-height:1.8;color:#7b899e;margin-top:14px}.more-plan{display:flex;justify-content:space-between;align-items:center;margin-top:24px;font-size:12px}.more-plan>span{color:#8694a8}.more-plan a{background:#2877ed;color:white;border-radius:7px;padding:11px 16px;text-decoration:none}details{font-size:11px;color:#8694a8;line-height:1.9;margin-top:12px}summary{cursor:pointer}@media(max-width:650px){.recommend-grid{grid-template-columns:1fr}.agent-route-map{height:320px}.agent-route-map :deep(.planning-map){min-height:320px}.comparison-row>span{width:85px}.more-plan{gap:12px;flex-wrap:wrap}}</style>
